import { PrismaClient } from "~/generated/prisma/client";
import { PrismaD1 } from "@prisma/adapter-d1";

export let prisma: ReturnType<typeof createPrisma>;

export const createPrisma = (_db: D1Database) => {
  const adapter = new PrismaD1(_db);
  return new PrismaClient({
    adapter,
    log: ["error"],
  });
};

export const initPrisma = (db: D1Database) => {
  if (prisma) return;
  prisma = createPrisma(db);
};

