===================================================================
--- /root/.config/worktrees/cloudflare-worker-demo-migrate-drizzle/packages/db/src/schema/relations.ts
+++ /root/.config/worktrees/cloudflare-worker-demo-migrate-drizzle/packages/db/src/schema/relations.ts
@@ -0,0 +1,57 @@
+import { relations } from "drizzle-orm";
+
+import { accounts } from "./accounts";
+import { activities } from "./activities";
+import { activityGoals } from "./activity-goals";
+import { periods } from "./periods";
+import { roles, roleToUser } from "./roles";
+import { sessions } from "./sessions";
+import { users } from "./users";
+
+export const usersRelations = relations(users, ({ many }) => ({
+  activities: many(activities),
+  periods: many(periods),
+  goals: many(activityGoals),
+  sessions: many(sessions),
+  accounts: many(accounts),
+  roleLinks: many(roleToUser),
+}));
+
+export const activitiesRelations = relations(activities, ({ one, many }) => ({
+  user: one(users, { fields: [activities.userId], references: [users.id] }),
+  periods: many(periods),
+  goals: many(activityGoals),
+}));
+
+export const periodsRelations = relations(periods, ({ one }) => ({
+  activity: one(activities, {
+    fields: [periods.activityId],
+    references: [activities.id],
+  }),
+  user: one(users, { fields: [periods.userId], references: [users.id] }),
+}));
+
+export const activityGoalsRelations = relations(activityGoals, ({ one }) => ({
+  activity: one(activities, {
+    fields: [activityGoals.activityId],
+    references: [activities.id],
+  }),
+  user: one(users, { fields: [activityGoals.userId], references: [users.id] }),
+}));
+
+export const sessionsRelations = relations(sessions, ({ one }) => ({
+  user: one(users, { fields: [sessions.userId], references: [users.id] }),
+}));
+
+export const accountsRelations = relations(accounts, ({ one }) => ({
+  user: one(users, { fields: [accounts.userId], references: [users.id] }),
+}));
+
+export const rolesRelations = relations(roles, ({ many }) => ({
+  userLinks: many(roleToUser),
+}));
+
+export const roleToUserRelations = relations(roleToUser, ({ one }) => ({
+  user: one(users, { fields: [roleToUser.userId], references: [users.id] }),
+  role: one(roles, { fields: [roleToUser.roleId], references: [roles.id] }),
+}));

